/**

For "Glyphs" #WCCChallenge by Neha N

A grid of rotating 3D planes with simple glyph-like forms, built using Three.js in p5.js. 
Each tile moves using sine and cosine functions with randomized speed and phase offset, creating smooth, desynchronized motion across the grid.
**/

let scene, camera, renderer;
let tiles = [];

function setup() {
  noCanvas();

  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050505);

  camera = new THREE.PerspectiveCamera(
    60,
    windowWidth / windowHeight,
    0.1,
    100
  );
  camera.position.set(0, 0, 12);

  renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(windowWidth, windowHeight);
  document.body.appendChild(renderer.domElement);

  let ambient = new THREE.AmbientLight(0xffffff, 0.45);
  scene.add(ambient);

  let light = new THREE.DirectionalLight(0xffffff, 1.2);
  light.position.set(3, 4, 6);
  scene.add(light);

  createGrid();
}


function draw(){
  let t = millis() * 0.001;
  let bE = (window.beatEnergy || 0.0);
  let bassE = (window.bassEnergy || 0.0);
  let midE = (window.midEnergy || 0.0);
  let highE = (window.highEnergy || 0.0);

  for (let i = 0; i < tiles.length; i++) {
    let tile = tiles[i];

    tile.rotation.y =
      Math.sin(t * (tile.userData.speed + bassE * 2.0) + tile.userData.offset) * (0.45 + bE * 0.4);

    tile.rotation.x =
      Math.cos(t * (tile.userData.speed + midE * 1.5) + tile.userData.offset) * (0.25 + bE * 0.3);

    tile.rotation.z =
      Math.sin(t * 0.3 + i) * 0.04 + highE * 0.5;
  }

  renderer.render(scene, camera);
}


function createGrid() {
  let cols = 9;
  let rows = 6;
  let spacing = 1.8;

  for (let x = 0; x < cols; x++) {
    for (let y = 0; y < rows; y++) {
      let tile = createTile();

      tile.position.x = (x - (cols - 1) /2 ) * spacing;
      tile.position.y = (y - (rows - 1) /2 ) * spacing;

      tile.userData.offset = random(TWO_PI);
      tile.userData.speed = random(0.4, 1.1);

      scene.add(tile);
      tiles.push(tile);
    }
  }
}

function createTile(){

	let group = new THREE.Group();
	let plane = new THREE.Mesh(
		new THREE.PlaneGeometry(1.3, 1.3),
		new THREE.MeshStandardMaterial(
			{color:0x180028, 
			roughness: 0.8, 
			metalness: 0.1,
			side: THREE.DoubleSide}
		),
	);
	group.add(plane);

	let glyphMaterial = new THREE.MeshStandardMaterial(
		{
			color: 0x00f0ff,
		   roughness: 0.35,
         metalness: 0.25
		}
	);

	let type = floor(random(5));
  if (type === 0) addLineGlyph(group, glyphMaterial);
  if (type === 1) addCrossGlyph(group, glyphMaterial);
  if (type === 2) addRingGlyph(group, glyphMaterial);
  if (type === 3) addDotGlyph(group, glyphMaterial);
  if (type === 4) addTriangleGlyph(group, glyphMaterial);

  return group;
}

function addLineGlyph(group, material){
	let line = new THREE.Mesh(
		new THREE.BoxGeometry(0.08, 0.7, 0.05 ), 
		material
	);
	line.position.z = 0.05;
	line.rotation.z = random(Math.PI);
	group.add(line);

}

function addCrossGlyph(group, mat) {
  let vertical = new THREE.Mesh(
    new THREE.BoxGeometry(0.07, 0.7, 0.05),
    mat
  );

  let horizontal = new THREE.Mesh(
    new THREE.BoxGeometry(0.55, 0.07, 0.05),
    mat
  );

  vertical.position.z = 0.05;
  horizontal.position.z = 0.06;

  let angle = random(Math.PI);
  vertical.rotation.z = angle;
  horizontal.rotation.z = angle;

  group.add(vertical);
  group.add(horizontal);
}

function addRingGlyph(group, mat) {
  let ring = new THREE.Mesh(
    new THREE.TorusGeometry(0.28, 0.025, 12, 48),
    mat
  );

  ring.position.z = 0.06;
  group.add(ring);
}

function addDotGlyph(group, mat) {
  for (let i = 0; i < 5; i++) {
    let dot = new THREE.Mesh(
      new THREE.SphereGeometry(0.045, 12, 12),
      mat
    );

    dot.position.set(
      random(-0.275, 0.275),
      random(-0.275, 0.275),
      0.07
    );

    group.add(dot);
  }
}

function addTriangleGlyph(group, mat) {
  let tri = new THREE.Mesh(
    new THREE.ConeGeometry(0.32, 0.55, 3),
    mat
  );

  tri.position.z = 0.06;
  tri.rotation.z = random(Math.PI);
  group.add(tri);
}

function windowResized() {
  camera.aspect = windowWidth / windowHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(windowWidth, windowHeight);
}

